    $n=0;foreach(array_reverse(x25_store()->all()) as $rec) {
        if(($rec['edition_slug']??x25_default_slug())!==$slug||$rec['status']!=='zugelassen') { continue; }
        $n++;$number=str_pad((string)$n,2,'0',STR_PAD_LEFT);
        $body.='<section class="sheet"><p class="eyebrow">'.$h($ed['thema']).' · EDITION 01 · PLATZ '.$number.'/25</p><h2>'.$h($rec['name']).'</h2><p>'.$h($rec['company']).'</p>';
        if($type==='platzkarten') { $body.='<p class="serif">'.$h($rec['care']['welcome']??'Schön, dass Du Teil dieser Runde bist.').'</p><p>'.$h($ed['datum_text']).' · Köln, Rheinauhafen</p>'; }
        else { $body.='<h3>Was wird bis zur nächsten Edition eintreten?</h3><div class="write"></div><h3>Wie sicher bist Du Dir? 0–100 %</h3><div class="write short"></div><h3>Welche Entscheidung folgt daraus?</h3><div class="write"></div><p>Datum und Unterschrift</p><div class="write short"></div><p>Du öffnest Dein Kuvert bei der nächsten Edition desselben Themas. Was Du daraus teilst, entscheidest Du.</p>'; }
